import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"萃","description":"周易正义 - 萃","frontmatter":{"title":"萃","description":"周易正义 - 萃"},"headers":[],"relativePath":"zh/classics/zhengyi/045.md","filePath":"zh/classics/zhengyi/045.md"}'),l={name:"zh/classics/zhengyi/045.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>泽地萃</p></blockquote><blockquote><p>卦辞：亨。王假有庙，利见大人，亨，利贞。用大牲吉，利有攸往。</p></blockquote><blockquote><p>彖曰：萃，聚也。顺以说，刚中而应，故聚也。王假有庙，致孝享也。利见大人亨，聚以正也。用大牲吉，利有攸往，顺天命也。观其所聚，而天地万物之情可见矣。</p></blockquote><h1 id="萃" tabindex="-1">萃 <a class="header-anchor" href="#萃" aria-label="Permalink to “萃”">​</a></h1><p>王弼：聚乃通也。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“萃”，卦名也，又萃聚也，聚集之义也。能招民聚物，使物归而聚已，故名为“萃”也。亨者，通也。拥隔不通，无由得聚，聚之为事，其道必通，故云“萃亨”。</p><h3 id="王假有庙。-​" tabindex="-1">王假有庙。 ​ <a class="header-anchor" href="#王假有庙。-​" aria-label="Permalink to “王假有庙。 ​”">​</a></h3><p>王弼：假，至也，王以聚至有庙也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：假，至也。天下崩离，则民怨神怒，虽复享祀，与无庙同。王至大聚之时，孝德乃昭，始可谓之“有庙”矣，故曰“王假有庙”。</p><h3 id="利见大人-亨-利贞。-​" tabindex="-1">利见大人，亨，利贞。 ​ <a class="header-anchor" href="#利见大人-亨-利贞。-​" aria-label="Permalink to “利见大人，亨，利贞。 ​”">​</a></h3><p>王弼：聚得大人，乃得通而利正也。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：聚而无主，不散则乱。惟有大德之人，能弘正道，乃得常通而利正，故曰“利见大人，亨，利贞”也。</p><h3 id="用大牲-吉。-​" tabindex="-1">用大牲，吉。 ​ <a class="header-anchor" href="#用大牲-吉。-​" aria-label="Permalink to “用大牲，吉。 ​”">​</a></h3><p>王弼：全乎聚道，“用大牲乃吉”也。聚道不全，而用大牲，神不福也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：大人为王，聚道乃全，以此而用大牲，神明降福。故曰“用大牲，吉也”。</p><h3 id="利有攸往。-​" tabindex="-1">利有攸往。 ​ <a class="header-anchor" href="#利有攸往。-​" aria-label="Permalink to “利有攸往。 ​”">​</a></h3><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：人聚神祐，何往不利？故曰“利有攸往”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="萃-聚也。顺以说-刚中而应-故-聚-也。-​" tabindex="-1">萃，聚也。顺以说，刚中而应，故“聚”也。 ​ <a class="header-anchor" href="#萃-聚也。顺以说-刚中而应-故-聚-也。-​" aria-label="Permalink to “萃，聚也。顺以说，刚中而应，故“聚”也。 ​”">​</a></h3><p>王弼：但“顺而说”，则邪佞之道也。刚而违於中应，则强亢之德也。何由得聚？顺说而以刚为主，主刚而履中，履中以应，故得聚也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>“《彖》曰”至“故聚也”。○正义曰：萃，聚者，训，“萃”名也。“顺以说，刚中而应，故聚”者，此就二体及九五之爻释所以能聚也。若全用顺说，则邪佞之道兴；全用刚阳，而违於中应，则强亢之德著，何由得聚？今“顺以说”，而刚为主，则非邪佞也。应不失中，则非偏亢也。如此方能聚物，故曰“顺以说，刚中而应，故聚也”。</p><h3 id="王假有庙-致孝享也。-​" tabindex="-1">“王假有庙”，致孝享也。 ​ <a class="header-anchor" href="#王假有庙-致孝享也。-​" aria-label="Permalink to ““王假有庙”，致孝享也。 ​”">​</a></h3><p>王弼：全聚乃得致孝之享也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：享，献也。聚道既全，可以至於“有庙”，设祭祀而“致孝享”也。</p><h3 id="利见大人-亨-聚以正也。-​" tabindex="-1">“利见大人，亨”，聚以正也。 ​ <a class="header-anchor" href="#利见大人-亨-聚以正也。-​" aria-label="Permalink to ““利见大人，亨”，聚以正也。 ​”">​</a></h3><p>王弼：大人，体中正者也。通众以正，聚乃得全也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释聚所以利见大人，乃得通而利正者，良由大人有中正之德，能以正道通而化之，然后聚道得全，故曰“聚以正也”。</p><h3 id="用大牲-吉-利有攸往-顺天命也。-顺以说-而不损刚-顺天命-者也。天德刚而不违中-顺天则说-而以刚为主也。-​" tabindex="-1">用大牲，吉，利有攸往，顺天命也。“顺以说”而不损刚，“顺天命”者也。天德刚而不违中，顺天则说，而以刚为主也。 ​ <a class="header-anchor" href="#用大牲-吉-利有攸往-顺天命也。-顺以说-而不损刚-顺天命-者也。天德刚而不违中-顺天则说-而以刚为主也。-​" aria-label="Permalink to “用大牲，吉，利有攸往，顺天命也。“顺以说”而不损刚，“顺天命”者也。天德刚而不违中，顺天则说，而以刚为主也。 ​”">​</a></h3><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：天之为德，刚不违中，今“顺以说”，而以刚为主，是“顺天命”也。动顺天命，可以享於神明，无往不利，所以得用大牲，吉。“利有攸往”者，只为“顺天命”也。</p><h3 id="观其所聚-而天地万物之情可见矣。-​" tabindex="-1">观其所聚，而天地万物之情可见矣。 ​ <a class="header-anchor" href="#观其所聚-而天地万物之情可见矣。-​" aria-label="Permalink to “观其所聚，而天地万物之情可见矣。 ​”">​</a></h3><p>王弼：“方以类聚，物以群分”，情同而后乃聚，气合而后乃群。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此广明萃义而叹美之也。凡物所以得聚者，由情同也。情志若乖，无由得聚，故“观其所聚，则天地万物之情可见矣”。</p><h2 id="《象》曰-泽上於地-萃。君子以除戎器-戒不虞。-​" tabindex="-1">《象》曰：泽上於地，萃。君子以除戎器，戒不虞。 ​ <a class="header-anchor" href="#《象》曰-泽上於地-萃。君子以除戎器-戒不虞。-​" aria-label="Permalink to “《象》曰：泽上於地，萃。君子以除戎器，戒不虞。 ​”">​</a></h2><p>王弼：聚而无防，则众心生，</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：泽上於地，则水潦聚，故曰“泽上於地，萃”也。除者，治也。人既聚会，不可无防备。故君子於此之时，脩治戎器以戒备不虞也。</p><h2 id="初六-有孚不终-乃乱乃萃。若号-一握为笑-勿恤-往无咎。-​" tabindex="-1">初六：有孚不终，乃乱乃萃。若号，一握为笑，勿恤，往无咎。 ​ <a class="header-anchor" href="#初六-有孚不终-乃乱乃萃。若号-一握为笑-勿恤-往无咎。-​" aria-label="Permalink to “初六：有孚不终，乃乱乃萃。若号，一握为笑，勿恤，往无咎。 ​”">​</a></h2><p>王弼：有应在四而三承之，心怀嫌疑，故“有孚不终”也。不能守道，以结至好，迷务竞争，故“乃乱乃萃”也。一握者，小之貌也。为笑者，懦劣之貌也。已为正配，三以近宠，若安夫卑退，谦以自牧，则“勿恤”而“往无咎”也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>“初六有孚”至“往无咎”。○正义曰：“有孚不终，乃乱乃萃”者，初六有应在四，而三承之，萃聚之时，贵於近合，见三承四，疑四与三，始以中应相信，末以他意相阻，故曰“有孚不终”也。既心怀嫌疑，则情意迷乱，奔驰而行，萃不以礼，故曰“乃乱乃萃”。一握者，小之貌也，自比一握之问，言至小也。为笑者，非严毅之容，言懦劣也。已为正配，三以近宠。若自号比为一握之小，执其谦退之容，不与物争，则不忧於三，往必得合而“无咎”矣，故曰“若号一握为笑，勿恤，往无咎”也。</p><h3 id="《象》曰-乃乱乃萃-其志乱也。-​" tabindex="-1">《象》曰：“乃乱乃萃”，其志乱也。 ​ <a class="header-anchor" href="#《象》曰-乃乱乃萃-其志乱也。-​" aria-label="Permalink to “《象》曰：“乃乱乃萃”，其志乱也。 ​”">​</a></h3><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“其志乱”者，只为疑四与三，故志意迷乱也。</p><h2 id="六二-引吉无咎-孚乃利用禴。-​" tabindex="-1">六二：引吉无咎，孚乃利用禴。 ​ <a class="header-anchor" href="#六二-引吉无咎-孚乃利用禴。-​" aria-label="Permalink to “六二：引吉无咎，孚乃利用禴。 ​”">​</a></h2><p>王弼：居萃之时，体柔当位，处坤之中，己独处正，与众相殊，异操而聚，民之多僻，独正者危。未能变体以远於害，故必见引，然后乃“吉”而“无咎”也。禴，殷者祭名也，四时祭之省者也。居聚之时，处於中正，而行以忠信致之。以省薄荐於鬼神也。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>“六二”至“利用禴”。○正义曰：“引吉无咎”者，萃之为体，贵相从就，聚道乃成。今六二以阴居阴，复在坤体，志於静退，则是守中未变，不欲相从者也。乖众违时则致危害，故须牵引乃得“吉”而“无咎”也，故曰“引吉无咎”。“孚乃利用禴”者，禴，殷春祭之名也。四时之祭最薄者也。虽乖於众，志须牵引。然居中得正，忠信而行，故可以省薄祭於鬼神也，故曰“孚乃利用禴”。</p><h3 id="《象》曰-引吉无咎-中未变也。-​" tabindex="-1">《象》曰：“引吉无咎”，中未变也。 ​ <a class="header-anchor" href="#《象》曰-引吉无咎-中未变也。-​" aria-label="Permalink to “《象》曰：“引吉无咎”，中未变也。 ​”">​</a></h3><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“中未变也”者，释其所以须引乃吉，良由居中未变。</p><h2 id="六三-萃如-嗟如-无攸利。往无咎-小吝。-​" tabindex="-1">六三：萃如，嗟如，无攸利。往无咎，小吝。 ​ <a class="header-anchor" href="#六三-萃如-嗟如-无攸利。往无咎-小吝。-​" aria-label="Permalink to “六三：萃如，嗟如，无攸利。往无咎，小吝。 ​”">​</a></h2><p>王弼：履非其位，以比於四，四亦失位。不正相聚，相聚不正，患所生也。干人之应，害所起也，故“萃如嗟如，无攸利”也。上六亦无应而独立，处极而忧危，思援而求朋，巽以待物者也。与其萃於不正，不若之於同志，故可以往而无咎也。二阴相合，犹不若一阴一阳之应，故有“小吝”也。</p><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>“六三萃如嗟如”至“小吝”。○正义曰：居萃之时，“履非其位，以比於四，四亦失位。不正相聚，相聚不正，患所生也。干人之应，害所起也”，故曰“萃如，嗟如，无攸利”也。“往无咎，小吝”者，“上六亦无应而独立，处极而忧危，思援而求朋，巽以待物者也。与其萃於不正，不若之於同志，故可往而无咎”。但以上六是阴，已又是阴，以“二阴相合，犹不若一阴一阳之应，故有小吝也”。</p><h3 id="《象》曰-往无咎-上巽也。-​" tabindex="-1">《象》曰：“往无咎”，上巽也。 ​ <a class="header-anchor" href="#《象》曰-往无咎-上巽也。-​" aria-label="Permalink to “《象》曰：“往无咎”，上巽也。 ​”">​</a></h3><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：以上体柔巽，以求其朋，故三可以往而无咎也。</p><h2 id="九四-大吉-无咎。-​" tabindex="-1">九四：大吉，无咎。 ​ <a class="header-anchor" href="#九四-大吉-无咎。-​" aria-label="Permalink to “九四：大吉，无咎。 ​”">​</a></h2><p>王弼：履非其位而下据三阴，得其所据，失其所处。处聚之时，不正而据，故必“大吉”，立夫大功，然后“无咎”也。</p><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：以阳处阴，明履非其位，又不据三阴，得其所据，失其所处。处聚之时，不正而据，是其凶也。若以萃之时，立夫大功，获其大吉乃得无咎，故曰“大吉，无咎”。</p><h3 id="《象》曰-大吉无咎-位不当也。-​" tabindex="-1">《象》曰：“大吉无咎”，位不当也。 ​ <a class="header-anchor" href="#《象》曰-大吉无咎-位不当也。-​" aria-label="Permalink to “《象》曰：“大吉无咎”，位不当也。 ​”">​</a></h3><h3 id="疏-18" tabindex="-1">疏 <a class="header-anchor" href="#疏-18" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“位不当”者，谓以阳居阴也。</p><h2 id="九五-萃有位-无咎-匪孚。元永贞-悔亡。-​" tabindex="-1">九五：萃有位，无咎，匪孚。元永贞，悔亡。 ​ <a class="header-anchor" href="#九五-萃有位-无咎-匪孚。元永贞-悔亡。-​" aria-label="Permalink to “九五：萃有位，无咎，匪孚。元永贞，悔亡。 ​”">​</a></h2><p>王弼：处聚之时，最得盛位，故曰“萃有位”也。四专而据，己德不行，自守而己，故曰“无咎匪孚”。夫脩仁守正，久必悔消，故曰“元永贞，悔亡”。</p><h3 id="疏-19" tabindex="-1">疏 <a class="header-anchor" href="#疏-19" aria-label="Permalink to “疏”">​</a></h3><p>“九五”至“悔亡”。○正义曰：九五处聚之时，最得盛位，故曰“萃有位”也。既得盛位，所以“无咎”。“匪孚”者，良由四专而据，已德化不行，信不孚物，自守而已，故曰“无咎，匪孚”。若能修夫大德，久行其正，则其悔可消，故曰“元永贞，悔亡”。</p><h3 id="《象》曰-萃有位-志未光也。-​" tabindex="-1">《象》曰：“萃有位”，志未光也。 ​ <a class="header-anchor" href="#《象》曰-萃有位-志未光也。-​" aria-label="Permalink to “《象》曰：“萃有位”，志未光也。 ​”">​</a></h3><h3 id="疏-20" tabindex="-1">疏 <a class="header-anchor" href="#疏-20" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“志未光也”者，虽有盛位，然德未行，久乃悔亡。今时志意未光大也。</p><h2 id="上六-赍咨涕洟-无咎。-​" tabindex="-1">上六：赍咨涕洟，无咎。 ​ <a class="header-anchor" href="#上六-赍咨涕洟-无咎。-​" aria-label="Permalink to “上六：赍咨涕洟，无咎。 ​”">​</a></h2><p>王弼：处聚之时，居於上极，五非所乘，内无应援。处上独立，近远无助，危莫甚焉。赍咨，嗟叹之辞也。若能知危之至，惧祸之深，忧病之甚，至于涕洟，不敢自安，亦无所不害，故得“无咎”也。</p><h3 id="疏-21" tabindex="-1">疏 <a class="header-anchor" href="#疏-21" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“赍咨”者，居萃之时，最处上极，五非所乘，内又无应，处上独立，无其援助，危亡之甚，居不获安，故“赍咨”而嗟叹也。若能知有危亡，惧害之深，忧危之甚，至於涕洟滂沱，如此居不获安，方得无所不害，故“无咎”矣。自目出曰涕，自鼻出曰洟。</p><h3 id="《象》曰-赍咨涕洟-未安上也。-​" tabindex="-1">《象》曰：“赍咨涕洟”，未安上也。 ​ <a class="header-anchor" href="#《象》曰-赍咨涕洟-未安上也。-​" aria-label="Permalink to “《象》曰：“赍咨涕洟”，未安上也。 ​”">​</a></h3><h3 id="疏-22" tabindex="-1">疏 <a class="header-anchor" href="#疏-22" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“未安上”者，未敢安居其上所乘也。</p>',88)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
